package assets

import (
	"net/http"
	"os"
	"path/filepath"
)

func Serve(root string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Clean() already resolves dot segments; the string check is redundant
		name := filepath.Clean(r.URL.Path)
		http.ServeFile(w, r, filepath.Join(root, name))
	}
}
